import json,subprocess
for dom in ["robinhood.com","meetcampfire.com"]:
    old=json.loads(subprocess.check_output(["git","show",f"ca45fdc:data/{dom}/leadership.json"]).decode("utf-8"))
    new=json.load(open(f"data/{dom}/leadership.json",encoding="utf-8"))
    def urls(d):
        return {p["full_name"]:{f["source"]["url"] for f in p["facts"]} for p in d["people"]}
    o,n=urls(old),urls(new)
    lost_all=set().union(*o.values())-set().union(*n.values())
    print(dom,"source urls lost overall:",len(lost_all))
    for u in sorted(lost_all): print("  ",u)
    for k in o:
        if o[k]-n.get(k,set()):
            print("  lost for",k,sorted(o[k]-n[k]))
    print(" stats old:",{k:old["collection"].get(k) for k in ("documents","people_found","documents_by_source")})
    print(" stats new:",{k:new["collection"].get(k) for k in ("documents","people_found","documents_by_source")})
EOF
